// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/version", wrapper.GetVersion)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/offline/version", wrapper.GetOfflineVersion)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/offline/packages", wrapper.PostOfflinePackages)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tiles/tianditu/{layer}/{z}/{x}/{y}", wrapper.GetTiandituTile)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/weather", wrapper.PostWeather)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/search", wrapper.GetSearch)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/code", wrapper.PostAuthCode)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.PostAuthLogin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.PostAuthLogout)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/me", wrapper.DeleteMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/sync", wrapper.GetSync)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sync", wrapper.PostSync)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sync/photos", wrapper.PostSyncPhoto)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/sync/photos/{photo}", wrapper.GetSyncPhoto)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/teams", wrapper.PostTeam)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/teams/join", wrapper.PostTeamJoin)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/teams/{id}", wrapper.GetTeam)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/teams/{id}/live", wrapper.GetTeamLive)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/teams/{id}/positions", wrapper.PostTeamPositions)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/teams/{id}/sharing", wrapper.PutTeamSharing)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/teams/{id}/leave", wrapper.PostTeamLeave)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/teams/{id}/end", wrapper.PostTeamEnd)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/teams/{id}/messages", wrapper.PostTeamMessage)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/teams/{id}/images", wrapper.PostTeamImage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/teams/{id}/images/{image}", wrapper.GetTeamImage)

	return m
}

